### 4. **Database Schema**

```php
// database/migrations/xxxx_create_pending_payments_table.php
Schema::create('pending_payments', function (Blueprint $table) {
    $table->id();
    $table->string('mpesa_transaction_id')->unique(); // Idempotency key
    $table->string('phone_number');
    $table->decimal('amount', 10, 2);
    $table->longText('raw_callback');
    $table->enum('status', ['received', 'allocated', 'manual_review', 'failed']);
    $table->foreignId('pupil_id')->nullable()->constrained();
    $table->string('review_reason')->nullable();
    $table->enum('source', ['callback', 'reconciliation'])->default('callback');
    $table->timestamp('received_at');
    $table->timestamp('processed_at')->nullable();
    $table->timestamps();

    $table->index('status');
    $table->index('received_at');
});

// Ensure transactions table has unique constraint
Schema::table('transactions', function (Blueprint $table) {
    $table->unique('mpesa_transaction_id');
});
```

