### 5. **Dashboard for Ops Team**

```php
// app/Http/Controllers/PaymentDashboardController.php
class PaymentDashboardController extends Controller
{
    public function index()
    {
        $stats = [
            'last_15_min' => PendingPayment::where('received_at', '>=', now()->subMinutes(15))
                ->count(),
            'allocated_15_min' => PendingPayment::where('status', 'allocated')
                ->where('processed_at', '>=', now()->subMinutes(15))
                ->count(),
            'manual_review' => PendingPayment::where('status', 'manual_review')
                ->where('processed_at', '>=', now()->subHours(1))
                ->get(),
            'failed_jobs' => Job::where('failed_at', '>=', now()->subHours(1))->count(),
        ];

        return view('dashboard', $stats);
    }
}
```

